package main

import (
	"encoding/xml"
	"fmt"
	"io"
	"strings"
)

func visibleText(source string) string {
	decoder := xml.NewDecoder(strings.NewReader(source))
	words := []string{}
	ignored := 0
	for {
		token, err := decoder.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return ""
		}
		switch value := token.(type) {
		case xml.StartElement:
			if value.Name.Local == "script" || value.Name.Local == "style" {
				ignored++
			}
		case xml.EndElement:
			if (value.Name.Local == "script" || value.Name.Local == "style") && ignored > 0 {
				ignored--
			}
		case xml.CharData:
			if ignored == 0 {
				words = append(words, strings.Fields(string(value))...)
			}
		}
	}
	return strings.Join(words, " " )
}

func main() {
	source := `<html><body><h1>Go makes crawlers clear.</h1><script>ignore()</script></body></html>`
	fmt.Println(visibleText(source))
}

