import (
	"encoding/xml"
	"fmt"
	"io"
	"net/url"
	"strings"
)

func absolute(baseURL, raw string) string {
	base, err := url.Parse(baseURL)
	if err != nil {
		return ""
	}
	reference, err := url.Parse(raw)
	if err != nil {
		return ""
	}
	resolved := base.ResolveReference(reference)
	if resolved.Scheme != "http" && resolved.Scheme != "https" {
		return ""
	}
	resolved.Fragment = ""
	return resolved.String()
}

func assets(baseURL, source string) []string {
	decoder := xml.NewDecoder(strings.NewReader(source))
	found := []string{}
	for {
		token, err := decoder.Token()
		if err == io.EOF {
			return found
		}
		start, ok := token.(xml.StartElement)
		if !ok {
			continue
		}
		wanted := map[string]string{"a": "href", "img": "src"}[start.Name.Local]
		for _, attribute := range start.Attr {
			if attribute.Name.Local == wanted {
				if item := absolute(baseURL, attribute.Value); item != "" {
					found = append(found, item)
				}
			}
		}
	}
}

func main() {
	source := `<main><a href="/docs#top">Docs</a><a href="mailto:team@example.com">Mail</a><img src="../logo.png"/></main>`
	for _, item := range assets("https://example.com/guides/start/", source) {
