package main

import (
	"flag"
	"fmt"
	"io"
	"time"
)

type config struct {
	Seed     string
	MaxPages int
	Timeout  time.Duration
	Output   string
}

func parseConfig(args []string) config {
	flags := flag.NewFlagSet("crawler", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	maxPages := flags.Int("max-pages", 10, "maximum pages")
	timeout := flags.Duration("timeout", 5*time.Second, "request timeout")
	output := flags.String("out", "report.json", "report path")
	if flags.Parse(args) != nil || flags.NArg() != 1 {
		return config{}
	}
	return config{Seed: flags.Arg(0), MaxPages: *maxPages, Timeout: *timeout, Output: *output}
}

func main() {
	args := []string{"-max-pages", "25", "-timeout", "3s", "-out", "report.json", "https://example.com"}
	cfg := parseConfig(args)
	fmt.Println(cfg.Seed, cfg.MaxPages, cfg.Timeout, cfg.Output)
}

