package main

import (
	"fmt"
	"sort"
	"strings"
	"sync"
)

func crawl(paths []string, workerCount int) ([]string, int) {
	jobs := make(chan string)
	results := make(chan string, len(paths))
	var workers sync.WaitGroup
	for worker := 0; worker < workerCount; worker++ {
		workers.Add(1)
		go func() {
			defer workers.Done()
			for path := range jobs {
				results <- strings.ToUpper(path)
			}
		}()
	}
	for _, path := range paths {
		jobs <- path
	}
	close(jobs)
	workers.Wait()
	close(results)
	found := make([]string, 0, len(paths))
	for result := range results {
		found = append(found, result)
	}
	sort.Strings(found)
	return found, workerCount
}

func main() {
	results, workers := crawl([]string{"/d", "/b", "/a", "/c"}, 2)
	fmt.Printf("workers=%d %s\n", workers, strings.Join(results, ","))
}

