package main

import (
	"fmt"
	"strings"
	"sync"
)

type limiter struct {
	mu    sync.Mutex
	seen  map[string]bool
	count int
	max   int
}

func (limit *limiter) reserve(page string) bool {
	limit.mu.Lock()
	defer limit.mu.Unlock()
	if limit.seen[page] || limit.count >= limit.max {
		return false
	}
	limit.seen[page] = true
	limit.count++
	return true
}

func main() {
	limit := limiter{seen: map[string]bool{}, max: 3}
	admitted := []string{}
	for _, page := range []string{"a", "b", "a", "c", "d"} {
		if limit.reserve(page) {
			admitted = append(admitted, page)
		}
	}
	fmt.Printf("%s count=%d\n", strings.Join(admitted, ","), limit.count)
}

